        jac[:, j, _OPPOSITE] = d - e*q*np.sin(q*y[:, _OPPOSITE])
        step = np.linalg.solve(jac, r[..., None])[..., 0]
        norm = np.sum(r*r, axis=1)
        trial = y - step
